from pathlib import Path
p = Path('Halo/Views/CaptureWorkspaceView.swift')
s = p.read_text()
old = '''    private func toolButton(_ title: String, _ symbol: String, prominent: Bool = false, action: @escaping () -> Void) -> some View {\n        Button(action: action) {\n            Label(title, systemImage: symbol)\n                .font(.caption.weight(.semibold))\n                .frame(maxWidth: .infinity, minHeight: 26)\n        }\n        .buttonStyle(prominent ? .borderedProminent : .bordered)\n        .disabled((service.busy || service.recording) && title != "Stop")\n    }\n'''
new = '''    @ViewBuilder private func toolButton(_ title: String, _ symbol: String, prominent: Bool = false, action: @escaping () -> Void) -> some View {\n        if prominent {\n            Button(action: action) {\n                Label(title, systemImage: symbol)\n                    .font(.caption.weight(.semibold))\n                    .frame(maxWidth: .infinity, minHeight: 26)\n            }\n            .buttonStyle(.borderedProminent)\n            .disabled((service.busy || service.recording) && title != "Stop")\n        } else {\n            Button(action: action) {\n                Label(title, systemImage: symbol)\n                    .font(.caption.weight(.semibold))\n                    .frame(maxWidth: .infinity, minHeight: 26)\n            }\n            .buttonStyle(.bordered)\n            .disabled((service.busy || service.recording) && title != "Stop")\n        }\n    }\n'''
if old not in s: raise SystemExit('Capture workspace toolButton anchor missing')
p.write_text(s.replace(old, new, 1))
